import XCTest

final class StandupTests: XCTestCase {
    func hittable(_ q: XCUIElementQuery) -> XCUIElement? {
        let els = q.allElementsBoundByIndex
        return els.first { $0.exists && $0.isHittable }
    }

    func testOpenRoom() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        sleep(2)
        let room = app.staticTexts.matching(identifier: "TitleLabel").matching(NSPredicate(format: "label == %@", "Team Standup"))
        let el = hittable(room)
        XCTAssertNotNil(el, "no hittable Team Standup")
        el!.tap()
        sleep(3)
        print("HIERARCHY_START")
        print(app.debugDescription)
        print("HIERARCHY_END")
    }
}
EOF
